-- [[ VARIABLES ]]
local Player = game.Players.LocalPlayer
local Cashiers = workspace:WaitForChild("Cashiers")
local Drops = workspace:WaitForChild("Ignored"):WaitForChild("Drop")
local Shop = workspace:WaitForChild("Ignored"):WaitForChild("Shop")
local RunService = game:GetService("RunService")

local Start_Cash = Player.DataFolder.Currency.Value
local BrokenBlacklist = {}

-- [[ THE STABILIZER ]]
-- Prevents flinging by stripping velocity and forcing noclip
RunService.Stepped:Connect(function()
    if Player.Character and Player.Character:FindFirstChild("HumanoidRootPart") then
        local root = Player.Character.HumanoidRootPart
        local hum = Player.Character:FindFirstChildOfClass("Humanoid")
        
        root.Velocity = Vector3.new(0,0,0)
        root.RotVelocity = Vector3.new(0,0,0)

        for _, v in pairs(Player.Character:GetDescendants()) do
            if v:IsA("BasePart") then v.CanCollide = false end
        end
        
        if _G.IsLaying then
            hum.PlatformStand = true
            root.CFrame = CFrame.new(root.Position) * CFrame.Angles(math.rad(90), 0, 0)
        else
            hum.PlatformStand = false
        end
    end
end)

-- [[ AUTO-MASK ]]
local function AutoMask()
    local maskModel = Shop:WaitForChild("[Ninja Mask] - $68", 5)
    if maskModel and maskModel:FindFirstChild("Head") then
        local char = Player.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local cd = maskModel:FindFirstChildOfClass("ClickDetector")

        if root and cd and hum then
            local oldPos = root.CFrame
            _G.IsLaying = false
            root.Anchored = false
            root.CFrame = maskModel.Head.CFrame * CFrame.new(0, 3, 0)
            task.wait(0.3)
            fireclickdetector(cd)
            task.spawn(function()
                local maskTool = Player.Backpack:WaitForChild("[Mask]", 5) 
                if maskTool then
                    hum:EquipTool(maskTool)
                    task.wait(0.2)
                    maskTool:Activate()
                end
            end)
            task.wait(0.3)
            root.CFrame = oldPos
        end
    end
end

local GetTarget = function()
    local root = Player.Character and Player.Character:FindFirstChild("HumanoidRootPart")
    if not root then return nil end
    local available = {}
    for _, v in pairs(Cashiers:GetChildren()) do
        local hum = v:FindFirstChild("Humanoid")
        local open = v:FindFirstChild("Open") or v:FindFirstChild("Wedge")
        if v.Name == "CA$HIER" and hum and hum.Health > 0 and open and not BrokenBlacklist[v] then
            table.insert(available, {obj = v, dist = (open.Position - root.Position).Magnitude})
        end
    end
    table.sort(available, function(a, b) return a.dist < b.dist end)
    return available[1] and available[1].obj or nil
end

-- [[ MAIN LOOP ]]
task.spawn(function()
    AutoMask()
    while true do
        task.wait(0.5)
        local char = Player.Character
        local hum = char and char:FindFirstChild("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")
        
        if not char or not hum or hum.Health <= 0 or not root then
            _G.IsLaying = false
            Player.CharacterAdded:Wait()
            task.wait(2)
            AutoMask()
            continue
        end
        
        local target = GetTarget()
        local tool = Player.Backpack:FindFirstChild("Combat") or char:FindFirstChild("Combat")

        if target and tool then
            local hitPart = target:FindFirstChild("Open") or target:FindFirstChild("Wedge")
            local targetX = hitPart.Position.X
            local isLMG = (math.abs(targetX - (-624.59845)) < 1 or math.abs(targetX - (-627.59845)) < 1)
            
            local offset = getgenv().FarmConfig.VerticalOffset
            local standPos = isLMG and ((targetX < -626) and Vector3.new(-631.280, 23.244, -289.877) or Vector3.new(-619.880, 23.244, -288.520)) or (hitPart.Position + Vector3.new(0, offset, 0))

            root.Anchored = false
            _G.IsLaying = not isLMG
            
            if isLMG then
                root.CFrame = CFrame.lookAt(standPos, hitPart.Position)
            else
                root.CFrame = CFrame.new(standPos) * CFrame.Angles(math.rad(90), 0, 0)
            end
            
            task.wait(0.1)
            root.Anchored = true
            hum:EquipTool(tool)

            local startTime = tick()
            while target and target.Humanoid.Health > 0 and (tick() - startTime) < 6 do
                tool:Activate()
                task.wait(0.4)
            end

            root.Anchored = false
            local collectStart = tick()
            while (tick() - collectStart) < 2.5 do
                local found = false
                for _, money in ipairs(Drops:GetChildren()) do
                    if money.Name == "MoneyDrop" and (money.Position - hitPart.Position).Magnitude <= 15 then
                        found = true
                        root.CFrame = CFrame.new(money.Position + Vector3.new(0, isLMG and 1.5 or offset, 0))
                        if not isLMG then root.CFrame *= CFrame.Angles(math.rad(90), 0, 0) end
                        if money:FindFirstChild("ClickDetector") then fireclickdetector(money.ClickDetector) end
                        task.wait(0.2)
                    end
                end
                if not found then break end
                task.wait(0.1)
            end

            _G.IsLaying = false
            root.Anchored = false
            BrokenBlacklist[target] = true
            task.delay(15, function() BrokenBlacklist[target] = nil end)
        end
    end
end)

